// Email Classification for Vietnamese users
const email = $input.first().json;
const subject = (email.subject || '').toLowerCase();
const from = (email.from || '').toLowerCase();
const body = (email.textPlain || email.body || '').toLowerCase();
const fullText = `${subject} ${from} ${body}`;

// VIP senders list - customize this list
const vipSenders = [
  'boss@company.com',
  'manager@company.com',
  'important-client@corp.com',
  'family@email.com',
  'spouse@email.com'
];

let category = 'normal';
let action = 'keep_inbox';
let label = '';
let priority = 'medium';
let notifyUser = false;

// Newsletter detection
const newsletterKeywords = [
  'unsubscribe', 'newsletter', 'digest', 'bản tin', 'hủy đăng ký',
  'no-reply', 'noreply', 'do-not-reply', 'mailing list'
];

// Promotion detection
const promoKeywords = [
  'sale', 'discount', '% off', 'giảm giá', 'khuyến mãi', 'flash sale',
  'ưu đãi', 'giảm sốc', 'deal hot', 'hot deal', 'miễn phí', 'free',
  'gift voucher', 'coupon', 'promo', 'offer', 'special offer',
  'black friday', 'cyber monday', 'tet sale', 'sale tet'
];

// Important/Urgent detection
const urgentKeywords = [
  'urgent', 'khẩn', 'important', 'gấp', 'emergency', 'ngay lập tức',
  'asap', 'immediately', 'deadline', 'hạn chót', 'cảnh báo', 'warning',
  'payment due', 'thanh toán', 'overdue', 'quá hạn'
];

// Classification logic
const hasNewsletterKeyword = newsletterKeywords.some(kw => fullText.includes(kw));
const hasPromoKeyword = promoKeywords.some(kw => fullText.includes(kw));
const hasUrgentKeyword = urgentKeywords.some(kw => fullText.includes(kw));
const isVipSender = vipSenders.some(sender => from.includes(sender));

if (isVipSender || hasUrgentKeyword) {
  category = 'important';
  action = 'star_and_notify';
  label = '⭐ Important';
  priority = 'high';
  notifyUser = true;
} else if (hasNewsletterKeyword) {
  category = 'newsletter';
  action = 'label_and_archive';
  label = '📬 Newsletter';
  priority = 'low';
} else if (hasPromoKeyword) {
  category = 'promotion';
  action = 'label_and_archive';
  label = '🏷️ Promotion';
  priority = 'low';
} else {
  category = 'normal';
  action = 'label_and_keep';
  label = '📥 Inbox';
  priority = 'medium';
}

// Confidence score based on keyword matches
const keywordCount = [
  ...newsletterKeywords,
  ...promoKeywords,
  ...urgentKeywords
].filter(kw => fullText.includes(kw)).length;

const confidence = Math.min(100, (keywordCount / 3) * 100);

return [{
  json: {
    ...email,
    category,
    action,
    label,
    priority,
    notify_user: notifyUser,
    confidence,
    keyword_count: keywordCount,
    classified_at: new Date().toISOString(),
    timezone: 'Asia/Ho_Chi_Minh'
  }
}];

